INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author, type) VALUES (
  'صحيح البخاري — حديث يا عبد الله، لا تكن مثل فلان؛ كان يقوم الليل، فترك قيام الليل',
  '
«قالَ لي رَسولُ اللَّهِ صلَّى اللهُ عليه وسلَّمَ: يا عَبْدَ اللَّهِ، لا تَكُنْ مِثْلَ فُلانٍ؛ كانَ يَقُومُ اللَّيْلَ، فَتَرَكَ قِيَامَ اللَّيْلِ!»
