INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author, type) VALUES (
  'صحيح البخاري — حديث أنا، فقال أنا أنا كأنه كرهها',
  '
«أَتَيْتُ النَّبيَّ صَلَّى اللهُ عليه وسلَّمَ في دَيْنٍ كانَ علَى أبِي، فَدَقَقْتُ البَابَ، فَقالَ: مَن ذَا؟ فَقُلتُ: أنَا، فَقالَ: أنَا أنَا! كَأنَّهُ كَرِهَهَا.»
