INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author, type) VALUES (
  'صحيح البخاري — حديث إنك ببطحاء مباركة
وقد أناخ بنا سالم يتوخى بالمناخ الذي كان عبد الله ينيخ',
  '
«عَنِ النبيِّ صلَّى اللهُ عليه وسلَّمَ: أنَّهُ رُئِيَ وهو في مُعَرَّسٍ بذِي الحُلَيْفَةِ ببَطْنِ الوَادِي، قيلَ له: إنَّكَ ببَطْحَاءَ مُبَارَكَةٍ.
