INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author, type) VALUES (
  'صحيح البخاري — حديث وأخبرني عبد الله، عن زيد بن ثابت أن رسول الله صلى الله عليه',
  '
«أنَّ رَسولَ اللَّهِ صَلَّى اللهُ عليه وسلَّمَ قالَ: لا تَبِيعُوا الثَّمَرَ حتَّى يَبْدُوَ صَلَاحُهُ، ولَا تَبِيعُوا الثَّمَرَ بالتَّمْرِ.
