INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author, type) VALUES (
  'صحيح البخاري — حديث كان في السبي صفية فصارت الى دحية الكلبي، ثم صارت الى النبي صلى',
  '
«كانَ في السَّبْيِ صَفِيَّةُ فَصَارَتِ الى دَحْيَةَ الكَلْبِيِّ، ثُمَّ صَارَتِ الى النبيِّ صَلَّى اللهُ عليه وسلَّمَ.»
